# ---- tests\test_semantic_cleanup.py ----
"""Tests for graph3d.semantic_cleanup.validate_semantic_fragment (#825)."""

import json

from graph3d import semantic_cleanup as sc


def _valid_fragment():
    return {
        "nodes": [{"id": "module_func", "label": "func", "file_type": "code"}],
        "edges": [{"source": "module_func", "target": "other_node"}],
        "hyperedges": [],
    }


def _case_test_semantic_cleanup_test_validate_semantic_fragment_accepts_valid():
    assert sc.validate_semantic_fragment(_valid_fragment()) == []


def _case_test_semantic_cleanup_test_validate_semantic_fragment_rejects_non_object():
    errors = sc.validate_semantic_fragment(["not", "an", "object"])
    assert any("object" in e.lower() for e in errors)


def _case_test_semantic_cleanup_test_validate_semantic_fragment_rejects_oversize_payload(monkeypatch):
    monkeypatch.setattr(sc, "MAX_SEMANTIC_FRAGMENT_BYTES", 64)
    fragment = _valid_fragment()
    fragment["nodes"][0]["label"] = "x" * 128
    errors = sc.validate_semantic_fragment(fragment)
    assert any("payload" in e.lower() for e in errors)


def _case_test_semantic_cleanup_test_validate_semantic_fragment_rejects_too_many_nodes(monkeypatch):
    monkeypatch.setattr(sc, "MAX_SEMANTIC_FRAGMENT_NODES", 1)
    fragment = _valid_fragment()
    fragment["nodes"].append({"id": "extra", "label": "extra", "file_type": "code"})
    errors = sc.validate_semantic_fragment(fragment)
    assert any("nodes" in e.lower() for e in errors)


def _case_test_semantic_cleanup_test_validate_semantic_fragment_rejects_too_many_edges(monkeypatch):
    monkeypatch.setattr(sc, "MAX_SEMANTIC_FRAGMENT_EDGES", 0)
    errors = sc.validate_semantic_fragment(_valid_fragment())
    assert any("edges" in e.lower() for e in errors)


def _case_test_semantic_cleanup_test_validate_semantic_fragment_rejects_path_separator_in_id():
    fragment = _valid_fragment()
    fragment["nodes"][0]["id"] = "../etc/passwd"
    errors = sc.validate_semantic_fragment(fragment)
    assert any("nodes[0].id" in e for e in errors)


def _case_test_semantic_cleanup_test_validate_semantic_fragment_rejects_invalid_file_type():
    fragment = _valid_fragment()
    fragment["nodes"][0]["file_type"] = "executable"
    errors = sc.validate_semantic_fragment(fragment)
    assert any("file_type" in e for e in errors)


def _case_test_semantic_cleanup_test_validate_semantic_fragment_accepts_rationale_file_type():
    """LLM output with file_type='rationale' must pass validation so the cleanup
    pass can convert or remove it.  Validation must not reject it before cleanup runs."""
    fragment = _valid_fragment()
    fragment["nodes"][0]["file_type"] = "rationale"
    errors = sc.validate_semantic_fragment(fragment)
    assert not any("file_type" in e for e in errors), (
        f"'rationale' must be accepted by validate_semantic_fragment; got errors: {errors}"
    )


def _case_test_semantic_cleanup_test_validate_semantic_fragment_accepts_concept_file_type():
    """LLM output with file_type='concept' must pass validation for the same reason."""
    fragment = _valid_fragment()
    fragment["nodes"][0]["file_type"] = "concept"
    errors = sc.validate_semantic_fragment(fragment)
    assert not any("file_type" in e for e in errors), (
        f"'concept' must be accepted by validate_semantic_fragment; got errors: {errors}"
    )


def _case_test_semantic_cleanup_test_load_validated_semantic_fragment_accepts_valid(tmp_path):
    chunk = tmp_path / ".graph3d_chunk_00.json"
    chunk.write_text(json.dumps(_valid_fragment()))
    fragment, errors = sc.load_validated_semantic_fragment(chunk)
    assert errors == []
    assert fragment == _valid_fragment()


def _case_test_semantic_cleanup_test_load_validated_semantic_fragment_rejects_oversize_before_parse(tmp_path, monkeypatch):
    """Oversize files are rejected by stat() — payload is never parsed."""
    monkeypatch.setattr(sc, "MAX_SEMANTIC_FRAGMENT_BYTES", 64)
    chunk = tmp_path / ".graph3d_chunk_99.json"
    # Write something that would PARSE successfully if read, but exceeds the size guard.
    chunk.write_text("[" + ",".join(['"x"'] * 50) + "]")
    fragment, errors = sc.load_validated_semantic_fragment(chunk)
    assert fragment is None
    assert any("payload" in e.lower() for e in errors)


def _case_test_semantic_cleanup_test_load_validated_semantic_fragment_rejects_invalid_json(tmp_path):
    """Invalid JSON returns an error instead of raising."""
    chunk = tmp_path / ".graph3d_chunk_bad.json"
    chunk.write_text("{not valid json")
    fragment, errors = sc.load_validated_semantic_fragment(chunk)
    assert fragment is None
    assert any("invalid json" in e.lower() for e in errors)


# ---------------------------------------------------------------------------
# Hyperedge validation (F2)
# ---------------------------------------------------------------------------


def _case_test_semantic_cleanup_test_validate_hyperedge_rejects_bad_id():
    fragment = _valid_fragment()
    fragment["hyperedges"] = [
        {"id": "../escape", "label": "x", "nodes": ["module_func", "module_func"]}
    ]
    errors = sc.validate_semantic_fragment(fragment)
    assert any("hyperedges[0].id" in e for e in errors)


def _case_test_semantic_cleanup_test_validate_hyperedge_rejects_bad_node_ref():
    fragment = _valid_fragment()
    fragment["hyperedges"] = [
        {"id": "valid_he", "label": "x", "nodes": ["module_func", "../bad_ref"]}
    ]
    errors = sc.validate_semantic_fragment(fragment)
    assert any("hyperedges[0].nodes[1]" in e for e in errors)


def _case_test_semantic_cleanup_test_validate_hyperedge_requires_list():
    fragment = _valid_fragment()
    fragment["hyperedges"] = [{"id": "valid_he", "label": "x", "nodes": "not a list"}]
    errors = sc.validate_semantic_fragment(fragment)
    assert any("hyperedges[0].nodes" in e for e in errors)


def _case_test_semantic_cleanup_test_validate_hyperedge_caps_count(monkeypatch):
    monkeypatch.setattr(sc, "MAX_SEMANTIC_FRAGMENT_HYPEREDGES", 1)
    fragment = _valid_fragment()
    fragment["hyperedges"] = [
        {"id": f"he_{i}", "label": "x", "nodes": ["module_func", "module_func"]} for i in range(3)
    ]
    errors = sc.validate_semantic_fragment(fragment)
    assert any("hyperedges has 3" in e for e in errors)


# ---------------------------------------------------------------------------
# Sanitizer behavior (F3 + F4 + rationale conversion)
# ---------------------------------------------------------------------------


def _case_test_semantic_cleanup_test_sanitize_drops_rationale_filetype_node():
    """A node with file_type='rationale' is removed wholesale."""
    fragment = {
        "nodes": [
            {"id": "real_node", "label": "Real", "file_type": "code"},
            {"id": "garbage", "label": "junk", "file_type": "rationale"},
        ],
        "edges": [],
        "hyperedges": [],
    }
    out = sc.sanitize_semantic_fragment(fragment)
    ids = {n["id"] for n in out["nodes"]}
    assert "real_node" in ids
    assert "garbage" not in ids


def _case_test_semantic_cleanup_test_sanitize_converts_sentence_rationale_node_to_attribute():
    """Sentence-like rationale node connected via `rationale_for` → attribute on target."""
    fragment = {
        "nodes": [
            {"id": "real_node", "label": "Real", "file_type": "code"},
            {
                "id": "why_node",
                "label": "We chose tree-sitter because the deterministic parser is faster than regex-based extraction.",
                "file_type": "rationale",
            },
        ],
        "edges": [{"source": "why_node", "target": "real_node", "relation": "rationale_for"}],
        "hyperedges": [],
    }
    out = sc.sanitize_semantic_fragment(fragment)
    ids = {n["id"] for n in out["nodes"]}
    assert "why_node" not in ids
    target = next(n for n in out["nodes"] if n["id"] == "real_node")
    assert "tree-sitter" in target.get("rationale", "")


def _case_test_semantic_cleanup_test_sanitize_converts_allowed_filetype_sentence_via_rationale_for_edge():
    """F3: a node with file_type='document' (allowed) that is BOTH sentence-like
    AND sources a `rationale_for` edge is still cleaned to an attribute."""
    fragment = {
        "nodes": [
            {"id": "real_node", "label": "Real", "file_type": "code"},
            {
                "id": "sentence_node",
                "label": (
                    "Decision: this node has sentence-like rationale text but uses an "
                    "allowed file_type, so it should not survive as a standalone graph node."
                ),
                "file_type": "document",
            },
        ],
        "edges": [{"source": "sentence_node", "target": "real_node", "relation": "rationale_for"}],
        "hyperedges": [],
    }
    out = sc.sanitize_semantic_fragment(fragment)
    ids = {n["id"] for n in out["nodes"]}
    assert "sentence_node" not in ids
    target = next(n for n in out["nodes"] if n["id"] == "real_node")
    assert "Decision" in target.get("rationale", "")


def _case_test_semantic_cleanup_test_sanitize_keeps_short_concept_named_node_with_punctuation():
    """A short named node with a period (e.g. abbreviation) is NOT sentence-like."""
    fragment = {
        "nodes": [
            {"id": "a_b", "label": "a.b.c", "file_type": "document"},
            {"id": "anchor", "label": "Anchor", "file_type": "code"},
        ],
        "edges": [{"source": "a_b", "target": "anchor", "relation": "rationale_for"}],
        "hyperedges": [],
    }
    out = sc.sanitize_semantic_fragment(fragment)
    ids = {n["id"] for n in out["nodes"]}
    assert "a_b" in ids
    assert "anchor" in ids


def _case_test_semantic_cleanup_test_sanitize_filters_hyperedges_after_node_removal():
    """F4: hyperedges referencing removed nodes are repaired or dropped."""
    fragment = {
        "nodes": [
            {"id": "real_node", "label": "Real", "file_type": "code"},
            {"id": "other", "label": "Other", "file_type": "code"},
            {"id": "garbage", "label": "junk", "file_type": "rationale"},
        ],
        "edges": [],
        "hyperedges": [
            {
                "id": "group_a",
                "label": "Group A",
                "nodes": ["garbage", "real_node", "other"],
                "relation": "participate_in",
            },
            {
                "id": "group_b",
                "label": "Group B (only one survivor)",
                "nodes": ["garbage", "real_node"],
                "relation": "participate_in",
            },
        ],
    }
    out = sc.sanitize_semantic_fragment(fragment)
    he_ids = {he["id"] for he in out["hyperedges"]}
    # group_a survives with garbage filtered out
    assert "group_a" in he_ids
    group_a = next(he for he in out["hyperedges"] if he["id"] == "group_a")
    assert "garbage" not in group_a["nodes"]
    assert set(group_a["nodes"]) == {"real_node", "other"}
    # group_b had only 1 surviving member → dropped
    assert "group_b" not in he_ids


def _case_test_semantic_cleanup_test_sanitize_drops_hyperedge_with_only_unknown_refs():
    """A hyperedge referencing only nodes not present in the fragment is dropped."""
    fragment = {
        "nodes": [{"id": "real_node", "label": "Real", "file_type": "code"}],
        "edges": [],
        "hyperedges": [{"id": "phantom", "label": "Phantom", "nodes": ["ghost1", "ghost2"]}],
    }
    out = sc.sanitize_semantic_fragment(fragment)
    assert out["hyperedges"] == []


def _case_test_semantic_cleanup_test_sanitize_boundary_sentence_threshold():
    """Boundary: a label with exactly 8 words + colon is sentence-like;
    a 7-word label without sentence punctuation is not."""
    # 8 words, has colon → sentence-like
    long_label = "Note: alpha beta gamma delta epsilon zeta eta"
    fragment = {
        "nodes": [
            {"id": "anchor", "label": "Anchor", "file_type": "code"},
            {"id": "n1", "label": long_label, "file_type": "rationale"},
        ],
        "edges": [{"source": "n1", "target": "anchor", "relation": "rationale_for"}],
        "hyperedges": [],
    }
    out = sc.sanitize_semantic_fragment(fragment)
    assert {n["id"] for n in out["nodes"]} == {"anchor"}
    anchor = out["nodes"][0]
    assert "alpha" in anchor.get("rationale", "")

    # 7 words no terminal punctuation → not sentence-like
    short_label = "alpha beta gamma delta epsilon zeta eta"
    fragment = {
        "nodes": [
            {"id": "anchor", "label": "Anchor", "file_type": "code"},
            {"id": "n2", "label": short_label, "file_type": "rationale"},
        ],
        "edges": [],
        "hyperedges": [],
    }
    out = sc.sanitize_semantic_fragment(fragment)
    # n2 has file_type=rationale, so it's still removed via pass 1 — but should NOT
    # become a rationale attribute on anchor (no rationale_for edge, no sentence pattern).
    assert {n["id"] for n in out["nodes"]} == {"anchor"}
    assert "rationale" not in out["nodes"][0]


def _case_test_semantic_cleanup_test_sanitize_rationale_only_propagates_through_rationale_for_edges():
    """A rationale node connected to ONE target via `rationale_for` and to ANOTHER
    target via a non-rationale-for relation must NOT attach the rationale text
    to the second target. Codex v2 caught the bug where every outgoing edge
    propagated the rationale, corrupting unrelated nodes."""
    fragment = {
        "nodes": [
            {"id": "rationale_target", "label": "Rationale Target", "file_type": "code"},
            {"id": "unrelated_target", "label": "Unrelated Target", "file_type": "code"},
            {
                "id": "why_node",
                "label": (
                    "Decision: we chose tree-sitter because the deterministic parser "
                    "is faster than regex-based extraction."
                ),
                "file_type": "rationale",
            },
        ],
        "edges": [
            {"source": "why_node", "target": "rationale_target", "relation": "rationale_for"},
            {"source": "why_node", "target": "unrelated_target", "relation": "references"},
        ],
        "hyperedges": [],
    }
    out = sc.sanitize_semantic_fragment(fragment)
    ids = {n["id"]: n for n in out["nodes"]}
    assert "why_node" not in ids
    # rationale_target should have the rationale attribute
    assert "tree-sitter" in ids["rationale_target"].get("rationale", "")
    # unrelated_target should NOT have rationale leaked from the `references` edge
    assert "rationale" not in ids["unrelated_target"]

# ---- tests\test_semantic_similarity.py ----
"""Tests for semantically_similar_to edge support."""
import networkx as nx
import pytest
from graph3d.build import build_from_json
from graph3d.analyze import surprising_connections, _surprise_score
from graph3d.report import generate


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _make_extraction_with_semantic_edge():
    """Two nodes in separate files connected by a semantically_similar_to edge."""
    return {
        "nodes": [
            {"id": "a_validate_input", "label": "validate_input", "file_type": "code",
             "source_file": "auth/validators.py", "source_location": "L5"},
            {"id": "b_check_input", "label": "check_input", "file_type": "code",
             "source_file": "api/checks.py", "source_location": "L12"},
        ],
        "edges": [
            {
                "source": "a_validate_input",
                "target": "b_check_input",
                "relation": "semantically_similar_to",
                "confidence": "INFERRED",
                "confidence_score": 0.82,
                "source_file": "auth/validators.py",
                "source_location": None,
                "weight": 0.82,
            }
        ],
        "input_tokens": 100,
        "output_tokens": 50,
    }


def _make_graph_with_semantic_edge():
    return build_from_json(_make_extraction_with_semantic_edge())


def _make_two_edge_graph():
    """Graph with one semantically_similar_to edge and one references edge, both cross-file."""
    G = nx.Graph()
    for nid, label, src in [
        ("a", "ValidateInput", "auth/validators.py"),
        ("b", "CheckInput", "api/checks.py"),
        ("c", "LoadConfig", "config/loader.py"),
        ("d", "ReadConfig", "utils/reader.py"),
    ]:
        G.add_node(nid, label=label, source_file=src, file_type="code")
    # semantically_similar_to edge
    G.add_edge("a", "b", relation="semantically_similar_to", confidence="INFERRED",
               confidence_score=0.82, source_file="auth/validators.py", weight=0.82,
               _src="a", _tgt="b")
    # plain references edge (same confidence tier)
    G.add_edge("c", "d", relation="references", confidence="INFERRED",
               confidence_score=0.7, source_file="config/loader.py", weight=0.7,
               _src="c", _tgt="d")
    return G


# ---------------------------------------------------------------------------
# Test 1: semantically_similar_to passes through build_from_json without being dropped
# ---------------------------------------------------------------------------

def _case_test_semantic_similarity_test_semantic_edge_survives_build_from_json():
    G = _make_graph_with_semantic_edge()
    assert G.number_of_edges() == 1
    u, v, data = next(iter(G.edges(data=True)))
    assert data["relation"] == "semantically_similar_to"


def _case_test_semantic_similarity_test_semantic_edge_nodes_present():
    G = _make_graph_with_semantic_edge()
    assert "a_validate_input" in G.nodes
    assert "b_check_input" in G.nodes


# ---------------------------------------------------------------------------
# Test 2: confidence_score is preserved for semantically_similar_to edges
# ---------------------------------------------------------------------------

def _case_test_semantic_similarity_test_semantic_edge_confidence_score_preserved():
    G = _make_graph_with_semantic_edge()
    u, v, data = next(iter(G.edges(data=True)))
    assert data.get("confidence_score") == pytest.approx(0.82)
    assert data.get("confidence") == "INFERRED"


# ---------------------------------------------------------------------------
# Test 3: surprising_connections scores semantically_similar_to edges higher
#         than references edges with the same community membership
# ---------------------------------------------------------------------------

def _case_test_semantic_similarity_test_semantic_edge_scores_higher_than_references():
    G = _make_two_edge_graph()
    communities = {0: ["a", "b"], 1: ["c", "d"]}
    node_community = {"a": 0, "b": 0, "c": 1, "d": 1}

    score_sem, reasons_sem = _surprise_score(
        G, "a", "b", G.edges["a", "b"], node_community,
        "auth/validators.py", "api/checks.py"
    )
    score_ref, _ = _surprise_score(
        G, "c", "d", G.edges["c", "d"], node_community,
        "config/loader.py", "utils/reader.py"
    )
    assert score_sem > score_ref


def _case_test_semantic_similarity_test_semantic_edge_reason_mentions_similarity():
    G = _make_two_edge_graph()
    communities = {0: ["a", "b"], 1: ["c", "d"]}
    node_community = {"a": 0, "b": 0, "c": 1, "d": 1}

    _, reasons = _surprise_score(
        G, "a", "b", G.edges["a", "b"], node_community,
        "auth/validators.py", "api/checks.py"
    )
    assert any("similar" in r for r in reasons)


# ---------------------------------------------------------------------------
# Test 4: report renders [semantically similar] tag for these edges
# ---------------------------------------------------------------------------

def _make_report_with_semantic_surprise():
    G = _make_graph_with_semantic_edge()
    communities = {0: ["a_validate_input", "b_check_input"]}
    cohesion = {0: 0.5}
    labels = {0: "Validators"}
    gods = []
    surprises = [
        {
            "source": "validate_input",
            "target": "check_input",
            "relation": "semantically_similar_to",
            "confidence": "INFERRED",
            "confidence_score": 0.82,
            "source_files": ["auth/validators.py", "api/checks.py"],
            "why": "semantically similar concepts with no structural link",
        }
    ]
    detection = {"total_files": 2, "total_words": 500, "needs_graph": True, "warning": None}
    tokens = {"input": 100, "output": 50}
    return generate(G, communities, cohesion, labels, gods, surprises, detection, tokens, "./project")


def _case_test_semantic_similarity_test_report_renders_semantically_similar_tag():
    report = _make_report_with_semantic_surprise()
    assert "[semantically similar]" in report


def _case_test_semantic_similarity_test_report_semantic_tag_on_correct_line():
    report = _make_report_with_semantic_surprise()
    for line in report.splitlines():
        if "semantically_similar_to" in line:
            assert "[semantically similar]" in line
            break
    else:
        pytest.fail("No line with semantically_similar_to found in report")


def _case_test_semantic_similarity_test_report_no_semantic_tag_for_other_relations():
    """Non-semantic edges must not get the [semantically similar] tag."""
    G = nx.Graph()
    for nid, label, src in [
        ("x", "Alpha", "repo1/a.py"),
        ("y", "Beta", "repo2/b.py"),
    ]:
        G.add_node(nid, label=label, source_file=src, file_type="code")
    G.add_edge("x", "y", relation="references", confidence="EXTRACTED",
               confidence_score=1.0, source_file="repo1/a.py", weight=1.0)

    communities = {0: ["x", "y"]}
    cohesion = {0: 0.5}
    labels = {0: "Misc"}
    gods = []
    surprises = [
        {
            "source": "Alpha",
            "target": "Beta",
            "relation": "references",
            "confidence": "EXTRACTED",
            "source_files": ["repo1/a.py", "repo2/b.py"],
            "why": "cross-file connection",
        }
    ]
    detection = {"total_files": 2, "total_words": 200, "needs_graph": True, "warning": None}
    tokens = {"input": 50, "output": 25}
    report = generate(G, communities, cohesion, labels, gods, surprises, detection, tokens, "./project")
    assert "[semantically similar]" not in report

# ---- tests\test_confidence.py ----
"""Tests for confidence_score on edges."""
import json
import tempfile
from pathlib import Path

import networkx as nx

from graph3d.build import build_from_json
from graph3d.cluster import cluster, score_all
from graph3d.analyze import god_nodes, surprising_connections
from graph3d.export import to_json
from graph3d.report import generate

FIXTURES = Path(__file__).parent / "fixtures"


def _make_extraction(**edge_overrides):
    """Return a minimal extraction dict with one edge of each confidence type."""
    base = {
        "nodes": [
            {"id": "n_a", "label": "A", "file_type": "code", "source_file": "a.py"},
            {"id": "n_b", "label": "B", "file_type": "code", "source_file": "b.py"},
            {"id": "n_c", "label": "C", "file_type": "document", "source_file": "c.md"},
            {"id": "n_d", "label": "D", "file_type": "document", "source_file": "d.md"},
        ],
        "edges": [
            {"source": "n_a", "target": "n_b", "relation": "calls", "confidence": "EXTRACTED",
             "confidence_score": 1.0, "source_file": "a.py", "weight": 1.0},
            {"source": "n_b", "target": "n_c", "relation": "implements", "confidence": "INFERRED",
             "confidence_score": 0.75, "source_file": "b.py", "weight": 0.8},
            {"source": "n_c", "target": "n_d", "relation": "references", "confidence": "AMBIGUOUS",
             "confidence_score": 0.2, "source_file": "c.md", "weight": 0.5},
        ],
        "input_tokens": 100,
        "output_tokens": 50,
    }
    return base


def _case_test_confidence_test_extracted_edges_have_score_1():
    """EXTRACTED edges must have confidence_score == 1.0."""
    G = build_from_json(_make_extraction())
    for u, v, d in G.edges(data=True):
        if d.get("confidence") == "EXTRACTED":
            assert d.get("confidence_score") == 1.0, (
                f"EXTRACTED edge ({u},{v}) should have confidence_score=1.0, got {d.get('confidence_score')}"
            )


def _case_test_confidence_test_inferred_edges_score_in_range():
    """INFERRED edges must have confidence_score between 0.0 and 1.0."""
    G = build_from_json(_make_extraction())
    found = False
    for u, v, d in G.edges(data=True):
        if d.get("confidence") == "INFERRED":
            found = True
            score = d.get("confidence_score")
            assert score is not None, f"INFERRED edge ({u},{v}) missing confidence_score"
            assert 0.0 <= score <= 1.0, (
                f"INFERRED edge ({u},{v}) confidence_score={score} out of range [0,1]"
            )
    assert found, "No INFERRED edges found in test fixture"


def _case_test_confidence_test_ambiguous_edges_score_at_most_04():
    """AMBIGUOUS edges must have confidence_score <= 0.4."""
    G = build_from_json(_make_extraction())
    found = False
    for u, v, d in G.edges(data=True):
        if d.get("confidence") == "AMBIGUOUS":
            found = True
            score = d.get("confidence_score")
            assert score is not None, f"AMBIGUOUS edge ({u},{v}) missing confidence_score"
            assert score <= 0.4, (
                f"AMBIGUOUS edge ({u},{v}) confidence_score={score} should be <= 0.4"
            )
    assert found, "No AMBIGUOUS edges found in test fixture"


def _case_test_confidence_test_confidence_score_round_trip():
    """confidence_score survives build_from_json → to_json → JSON parse round-trip."""
    extraction = _make_extraction()
    G = build_from_json(extraction)
    communities = cluster(G)

    with tempfile.TemporaryDirectory() as tmp:
        out = Path(tmp) / "graph.json"
        to_json(G, communities, str(out))
        data = json.loads(out.read_text())

    # to_json uses node_link_data which puts edges in "links"
    links = data.get("links", [])
    assert links, "No links found in exported graph.json"
    for link in links:
        assert "confidence_score" in link, f"Link missing confidence_score: {link}"
        score = link["confidence_score"]
        assert isinstance(score, float), f"confidence_score should be float, got {type(score)}"
        assert 0.0 <= score <= 1.0, f"confidence_score={score} out of range"


def _case_test_confidence_test_to_json_defaults_missing_confidence_score():
    """Edges lacking confidence_score get sensible defaults in to_json."""
    extraction = {
        "nodes": [
            {"id": "n_x", "label": "X", "file_type": "code", "source_file": "x.py"},
            {"id": "n_y", "label": "Y", "file_type": "code", "source_file": "y.py"},
            {"id": "n_z", "label": "Z", "file_type": "code", "source_file": "z.py"},
        ],
        "edges": [
            # No confidence_score field on any of these
            {"source": "n_x", "target": "n_y", "relation": "calls",
             "confidence": "EXTRACTED", "source_file": "x.py", "weight": 1.0},
            {"source": "n_y", "target": "n_z", "relation": "depends_on",
             "confidence": "INFERRED", "source_file": "y.py", "weight": 1.0},
        ],
        "input_tokens": 0,
        "output_tokens": 0,
    }
    G = build_from_json(extraction)
    communities = cluster(G)

    with tempfile.TemporaryDirectory() as tmp:
        out = Path(tmp) / "graph.json"
        to_json(G, communities, str(out))
        data = json.loads(out.read_text())

    links_by_conf = {}
    for link in data.get("links", []):
        conf = link.get("confidence", "EXTRACTED")
        links_by_conf[conf] = link.get("confidence_score")

    assert links_by_conf.get("EXTRACTED") == 1.0, "EXTRACTED default should be 1.0"
    assert links_by_conf.get("INFERRED") == 0.5, "INFERRED default should be 0.5"


def _case_test_confidence_test_report_shows_avg_confidence_for_inferred():
    """Report summary line should include avg confidence for INFERRED edges."""
    extraction = _make_extraction()
    G = build_from_json(extraction)
    communities = cluster(G)
    cohesion = score_all(G, communities)
    labels = {cid: f"Community {cid}" for cid in communities}
    gods = god_nodes(G)
    surprises = surprising_connections(G)
    detection = {"total_files": 2, "total_words": 5000, "needs_graph": True, "warning": None}
    tokens = {"input": 100, "output": 50}

    report = generate(G, communities, cohesion, labels, gods, surprises, detection, tokens, ".")
    assert "avg confidence" in report, "Report should show avg confidence for INFERRED edges"
    # The fixture has one INFERRED edge with score 0.75, so avg should be 0.75
    assert "0.75" in report, f"Expected avg confidence 0.75 in report"


def _case_test_confidence_test_report_inferred_tag_with_score():
    """Surprising connections section shows confidence score next to INFERRED edges."""
    # Build a graph where surprising_connections will find an INFERRED cross-file edge
    extraction = {
        "nodes": [
            {"id": "n_p", "label": "Parser", "file_type": "code", "source_file": "parser.py"},
            {"id": "n_q", "label": "Renderer", "file_type": "code", "source_file": "renderer.py"},
        ],
        "edges": [
            {"source": "n_p", "target": "n_q", "relation": "feeds",
             "confidence": "INFERRED", "confidence_score": 0.82,
             "source_file": "parser.py", "weight": 1.0},
        ],
        "input_tokens": 0,
        "output_tokens": 0,
    }
    G = build_from_json(extraction)

    # Manually construct a surprise entry the way analyze.surprising_connections would
    surprise = {
        "source": "Parser",
        "target": "Renderer",
        "relation": "feeds",
        "confidence": "INFERRED",
        "confidence_score": 0.82,
        "source_files": ["parser.py", "renderer.py"],
        "note": "",
    }
    communities = cluster(G)
    cohesion = score_all(G, communities)
    labels = {cid: f"Community {cid}" for cid in communities}
    gods = god_nodes(G)
    detection = {"total_files": 2, "total_words": 1000, "needs_graph": True, "warning": None}
    tokens = {"input": 0, "output": 0}

    report = generate(G, communities, cohesion, labels, gods, [surprise], detection, tokens, ".")
    assert "INFERRED 0.82" in report, (
        f"Report should show 'INFERRED 0.82' in surprising connections section. Got:\n{report}"
    )

# ---- tests\test_rationale.py ----
"""Tests for rationale/docstring extraction in extract.py."""
import textwrap
from pathlib import Path
import pytest
from graph3d.extract import extract_python
from graph3d.build import build_from_json


def _write_py(tmp_path: Path, code: str) -> Path:
    p = tmp_path / "sample.py"
    p.write_text(textwrap.dedent(code))
    return p


def _case_test_rationale_test_module_docstring_extracted(tmp_path):
    path = _write_py(tmp_path, '''
        """This module handles authentication because legacy sessions were insecure."""
        def login(): pass
    ''')
    result = extract_python(path)
    rationale = [n for n in result["nodes"] if n.get("file_type") == "rationale"]
    assert len(rationale) >= 1
    assert any("authentication" in n["label"] for n in rationale)


